 ('Battle Rope Waves','CARDIO','INTERMEDIATE','Alternating rope waves — intense upper body conditioning','Cardio','Shoulders',true),
 ('Sled Push','CARDIO','INTERMEDIATE','Push a weighted sled for distance — legs and lungs','Cardio','Legs',true),
 ('Assault Bike Sprint','CARDIO','BEGINNER','All-out sprint on an assault air bike — brutal metabolic conditioning','Cardio',NULL,false),
 ('Box Jump','CARDIO','BEGINNER','Explosive jump onto a box — plyometric power','Cardio','Legs',false),
 ('Sprint (Track / Treadmill)','CARDIO','BEGINNER','Short all-out running sprints — speed and fast-twitch development','Cardio',NULL,false),
 ('Stair Climber','CARDIO','BEGINNER','Continuous stair stepping — glutes and cardio combined','Cardio','Glutes',false),
 ('Swimming Laps','CARDIO','BEGINNER','Full-body low-impact cardio — great for recovery days','Cardio','Back',false),
 ('Elliptical','CARDIO','BEGINNER','Low-impact full-body cardio machine','Cardio',NULL,false),
 ('Jumping Jacks','CARDIO','BEGINNER','Full-body warm-up and conditioning exercise','Cardio',NULL,false)
) AS v(name, discipline, difficulty, instructions, primary_group, secondary_group, requires_weight)
WHERE NOT EXISTS (SELECT 1 FROM exercises e WHERE lower(e.name) = lower(v.name))
ORDER BY lower(v.name), v.primary_group;
